CREATE TABLE apartments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(120) NOT NULL, address VARCHAR(300) NOT NULL, total_units INTEGER NOT NULL CHECK(total_units > 0), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE households (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, apartment_id BIGINT NOT NULL REFERENCES apartments(id) ON DELETE CASCADE, flat_number VARCHAR(30) NOT NULL, flat_size_sqft INTEGER NOT NULL CHECK(flat_size_sqft > 0), occupancy_count INTEGER NOT NULL CHECK(occupancy_count > 0), has_meter BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE(apartment_id,flat_number));
CREATE TABLE users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, household_id BIGINT REFERENCES households(id) ON DELETE SET NULL, apartment_id BIGINT NOT NULL REFERENCES apartments(id) ON DELETE CASCADE, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(15) NOT NULL CHECK(role IN ('ADMIN','RESIDENT')), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE water_usage_logs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, household_id BIGINT NOT NULL REFERENCES households(id) ON DELETE CASCADE, reading_date DATE NOT NULL, meter_reading_kl NUMERIC(12,3) NOT NULL CHECK(meter_reading_kl >= 0), source VARCHAR(15) NOT NULL CHECK(source IN ('MANUAL','CSV_BULK')), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(household_id,reading_date));
CREATE TABLE tariff_plans (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, apartment_id BIGINT NOT NULL REFERENCES apartments(id) ON DELETE CASCADE, name VARCHAR(120) NOT NULL, base_threshold_kl NUMERIC(12,3) NOT NULL CHECK(base_threshold_kl >= 0), base_rate NUMERIC(12,3) NOT NULL CHECK(base_rate >= 0), excess_rate NUMERIC(12,3) NOT NULL CHECK(excess_rate >= 0), overuse_threshold_kl NUMERIC(12,3) NOT NULL CHECK(overuse_threshold_kl >= 0), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE billing_cycles (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, apartment_id BIGINT NOT NULL REFERENCES apartments(id) ON DELETE CASCADE, tariff_plan_id BIGINT NOT NULL REFERENCES tariff_plans(id), starts_on DATE NOT NULL, ends_on DATE NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','FINALIZED','ARCHIVED')), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE water_purchases (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, billing_cycle_id BIGINT NOT NULL REFERENCES billing_cycles(id) ON DELETE CASCADE, source VARCHAR(30) NOT NULL, purchased_on DATE NOT NULL, volume_kl NUMERIC(12,3) NOT NULL CHECK(volume_kl >= 0), unit_cost NUMERIC(12,3) NOT NULL CHECK(unit_cost >= 0), notes VARCHAR(255), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE invoices (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, billing_cycle_id BIGINT NOT NULL REFERENCES billing_cycles(id) ON DELETE CASCADE, household_id BIGINT NOT NULL REFERENCES households(id) ON DELETE CASCADE, consumption_kl NUMERIC(12,3) NOT NULL CHECK(consumption_kl >= 0), total_amount NUMERIC(12,3) NOT NULL CHECK(total_amount >= 0), status VARCHAR(20) NOT NULL DEFAULT 'UNPAID', created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE alerts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, apartment_id BIGINT REFERENCES apartments(id) ON DELETE CASCADE, household_id BIGINT REFERENCES households(id) ON DELETE CASCADE, type VARCHAR(50) NOT NULL, message VARCHAR(500) NOT NULL, resolved BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
